insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('banoffee-overnight-oats','Banoffee Overnight Oats','breakfast','🍌',1,521,18,72,18,array['Stir the oats, milk and half the Greek yoghurt together in a jar, cover and chill in the fridge overnight.','For the sauce, mash half the banana with the peanut butter and honey, loosening with a splash of milk until smooth and spoonable.','In the morning, slice the rest of the banana. Layer sauce and banana over the oats, top with the remaining Greek yoghurt and serve.']::text[],array['gluten','milk','peanuts']::text[],'live','idea: Mob',false,'e0261018fafba577',69,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
