insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('bbq-chicken-and-sweetcorn-rice','BBQ Chicken and Sweetcorn Rice','dinner','🍗',2,604,44,94,8,array['Cook the rice following the packet instructions, usually about 12 minutes, then drain and keep warm.','Meanwhile, heat a little oil in a large frying pan. Fry the diced chicken breast with the chopped pepper and onion for 8 minutes, stirring, until the chicken is golden and cooked through.','Stir in the barbecue sauce and sweetcorn and heat for 2 to 3 minutes until bubbling.','Divide the rice between two plates, spoon the BBQ chicken over the top and serve.']::text[],array['gluten']::text[],'live','table-plan',false,'037646f2bae02af5',185,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
