insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('bbq-chicken-gyros-cabbage-salad','Spiced Chicken Gyros with Cabbage Salad','dinner','🥙',2,691,64,40,29,array['Mix half the yoghurt with 15g of the oil, the lemon zest and juice, garlic, cumin, paprika, oregano and chilli flakes. Cut the chicken thighs into large chunks, coat well in the marinade, cover and chill for at least 2 hours.','Thread the chicken onto metal skewers. Shred the cabbage finely and toss with the sliced onion, tomatoes, chopped coriander, the rest of the oil and a pinch of salt.','Heat the grill to high and line a tray with foil. Grill the skewers for 8 to 10 minutes on each side, turning until charred and cooked through with no pink inside.','Warm the pittas under the grill for 1 minute, slice the chicken off the skewers and pile into the pittas with the cabbage salad. Spoon over the remaining yoghurt and serve.']::text[],array['gluten','milk']::text[],'live','idea: Morrisons Recipes (Good Food)',false,'9e2020a667694016',275,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
