insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('bbq-chicken-herb-slaw-wrap','BBQ Chicken Wrap with Herb Slaw','lunch','🌯',1,628,41,57,25,array['Rub the chicken breast with the smoked paprika, salt and pepper. Heat the oil in a frying pan over a high heat and cook the chicken for 3 to 4 minutes on each side, until golden and cooked through. Set aside to rest.','While the chicken cooks, shred the cabbage and grate the carrot into a bowl with a pinch of salt and massage for 2 minutes until softened. Stir in the yoghurt and mayonnaise, then the chopped coriander and finely chopped chilli.','Brush the chicken with the barbecue sauce and slice it. Spread the herb slaw down the middle of the wrap, top with the chicken and sliced avocado, then fold in the sides and roll up. Cut in half and serve.']::text[],array['eggs','gluten','milk','mustard']::text[],'live','idea: Joe Wicks',false,'057b51ade4b9667d',204,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
