insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('beef-burrito-bowl','Beef Burrito Bowl','dinner','🥗',4,505,27,64,16,array['Fry the chopped onion in half the oil over a high heat for 5 to 7 minutes until soft and starting to colour. Add the garlic for a minute, then the mince, breaking it up until browned.','Stir in the paprika, chilli flakes and tomato puree for a minute, then add the tinned tomatoes and half a tin of water. Simmer for 20 minutes.','Meanwhile quarter the cherry tomatoes and mix with the sliced spring onion and coriander for a salsa. Slice the avocado and squeeze over the lime.','Fry the sliced peppers in the rest of the oil for 3 to 4 minutes, add the drained beans and heat through. Cook the rice, then stir the peppers and beans through it.','Divide the rice between bowls and top with the chilli, salsa, avocado and a spoonful of yoghurt.']::text[],array['milk']::text[],'live','idea: Tesco Real Food',false,'58a09e035bb38398',215,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
