insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('budget-spring-roll-bowl','Pork Spring Roll Bowl','dinner','🥢',2,523,41,64,13,array['Cook the noodles following the pack instructions, then drain. Slice the mushrooms, shred the cabbage, grate the carrots and slice the spring onion.','Heat the oil in a large frying pan over a medium-high heat. Cook the pork mince with the crushed garlic for 4 to 5 minutes, breaking it up, until browned.','Add the mushrooms, cabbage and carrots and cook for about 10 minutes, stirring often, until the pork is cooked through and the vegetables are soft.','Stir in the soy sauce and season to taste with salt and pepper.','Divide the noodles between two bowls, top with the pork and vegetables and scatter over the spring onion.']::text[],array['eggs','gluten','soya']::text[],'live','idea: Joe Wicks',false,'aa80c65a7a85d972',150,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
