insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('caribbean-fish-curry','Caribbean Fish Curry','dinner','🍛',4,491,33,83,5,array['Fry the chopped onion, chilli and garlic in the oil for 5 minutes until soft, then stir in the paprika, curry powder and cumin and cook for 1 minute.','Add the diced sweet potato, then pour in 500ml hot water mixed with the crumbled stock cube and the lime juice. Simmer over a medium heat for 15 minutes until the sweet potato is tender.','While that simmers, cook the rice in plenty of boiling water for 12 minutes, then drain.','Add the cod in chunks and the halved tomatoes to the curry and simmer gently for 5 minutes, until the fish is opaque and flakes easily.','Spoon the rice into bowls, ladle over the curry and scatter with coriander to serve.']::text[],array['eggs','fish']::text[],'live','idea: Morrisons Recipes (Good Food)',false,'d2bd51f8f95b487b',500,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
