insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-bean-quesadillas','Chicken and Bean Quesadillas','dinner','🫓',2,800,62,79,26,array['Dice the chicken breast and chop the pepper. Fry in the oil with the fajita seasoning for 8 minutes until the chicken is cooked through, then stir in the drained kidney beans and warm for 1 minute.','Lay two wraps on a board and spread with the chicken and bean mix. Scatter over the grated cheddar and top with the other two wraps.','Toast each quesadilla in a dry frying pan over a medium heat for 2 to 3 minutes each side until golden and the cheese has melted.','Cut into wedges and serve.']::text[],array['gluten','milk','sulphites']::text[],'live','table-plan',false,'4230f40076517cb8',215,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
