insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-chorizo-rice','Chicken & Chorizo Rice','dinner','🍛',4,716,55,85,19,array['Fry the diced chorizo in a large lidded pan over a medium to high heat for 3 to 4 minutes until it has given up its oil and turned crisp, then lift it out and set it aside.','Add the chicken, cut into bite-sized pieces, to the chorizo oil and fry for 5 to 6 minutes until golden, then stir in the sliced peppers and the garlic and cook for 3 minutes more.','Stir in the paprika, tomato puree and rice, then pour in the stock made from the stock cubes and 600ml boiling water, and season with salt and pepper.','Cover, turn the heat right down and simmer for 15 to 20 minutes, stirring now and then, until the rice is tender and the chicken is cooked through.','Stir in the chickpeas and the crisp chorizo, heat through for 2 minutes and serve in bowls.']::text[],array['eggs']::text[],'live','idea: Joe Wicks',false,'77e6f167ed220043',212,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
