insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-egg-fried-rice','Chicken and Egg Fried Rice','lunch','🍳',1,584,41,66,19,array['Cook the rice following the pack instructions, then spread out to cool. Dice the chicken breast and slice the spring onion.','Fry the chicken in half the oil for 6 minutes, stirring, until golden and cooked through. Push to one side of the pan and scramble the eggs in the rest of the oil.','Add the cold rice, peas and soy sauce and stir-fry for 3 to 4 minutes until piping hot.','Scatter over the spring onion and serve.']::text[],array['eggs','gluten','soya']::text[],'live','table-plan',false,'8c0c8d618e43dd06',158,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
