insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-leek-pie','Chicken and Leek Pie','dinner','🥧',4,549,46,34,25,array['Heat the oven to 200C (180C fan). Melt the butter in a large frying pan over a medium heat and fry the chicken breast chunks for 6 minutes until golden.','Add the sliced leeks and cook for 5 minutes until softened. Stir in the mixed herbs, a stock cube dissolved in 150ml hot water, and the mustard.','Take the pan off the heat, stir in the yoghurt and season well, then tip into a baking dish.','Lay the pastry over the top, pinch the edges to seal and cut two slits in the middle. Bake for 20 to 25 minutes until the pastry is golden and the chicken is cooked through.','Steam the broccoli for 5 minutes, then serve it alongside slices of the pie.']::text[],array['eggs','gluten','milk','mustard','sulphites']::text[],'live','idea: Joe Wicks',false,'95ef12f04d8327ff',198,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
