insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-pineapple-kebabs-with-spicy-rice','Chicken and Pineapple Kebabs with Spicy Rice','dinner','🍍',2,551,39,65,16,array['Heat the grill to high. Thread the chicken thigh chunks, pineapple and quartered onion onto skewers, brush with half the oil and rub with the paprika, salt and pepper.','Grill the kebabs for 8 to 10 minutes, turning now and then, until the chicken is cooked through.','Meanwhile, boil the rice for 10 to 12 minutes, then drain well.','Heat the rest of the oil in a frying pan and fry the chopped spring onions for 2 minutes. Add the jerk seasoning and rice and fry for 3 minutes.','Serve the spicy rice with the kebabs, a spoonful of yoghurt and lime wedges.']::text[],array['milk','mustard']::text[],'live','idea: Joe Wicks',false,'65c0cccaefd5bfcf',203,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
