insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-and-tomato-gnocchi-bake','Chicken and Tomato Gnocchi Bake','dinner','🍅',2,604,48,60,17,array['Heat the oven to 220C (200C fan). Heat the oil in a saucepan over a medium-high heat and fry the bacon, chopped, for 3 to 4 minutes until crisp.','Add the garlic and fry for 1 minute, then stir in the tomato puree, chopped tomatoes and a mugful of boiling water. Simmer gently for 5 minutes.','Stir in the gnocchi and the roast chicken slices, torn up, and bring back to a simmer. Tip everything into an ovenproof dish.','Scatter the breadcrumbs and grated cheddar over the top and bake for 10 minutes until golden and bubbling.','Leave to settle for 2 minutes, then serve in bowls with a green salad.']::text[],array['gluten','milk']::text[],'live','idea: Joe Wicks',false,'28d09d842f6fdf77',318,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
