insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-chorizo-fajita-wraps','Chicken & Chorizo Fajita Wraps','dinner','🌯',2,831,54,79,33,array['Mash the avocado with the lime juice and a pinch of salt for a quick guacamole. Slice the peppers and onion, and cut the chicken into thin strips.','Fry the sliced chorizo in a dry pan over a medium heat for 3 to 4 minutes until the oil runs and it turns slightly crisp.','Add the peppers, onion and a little oil and cook for 5 minutes, stirring, until softened.','Stir in the chicken and fajita seasoning and stir-fry for 5 minutes until the chicken is cooked through with no pink inside.','Spread guacamole over each tortilla, spoon on the filling, a dollop of crème fraîche and the coriander, then roll up and serve.']::text[],array['gluten','milk','sulphites']::text[],'live','idea: Mob',false,'31bb2219826f985a',309,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
