insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-chorizo-traybake','Chicken & Chorizo Tray Bake','dinner','🍗',4,512,38,51,17,array['Heat the oven to 200C (180C fan). Chop the potatoes and sweet potatoes into chunky pieces, the onions into wedges and the peppers into strips, and tip everything into a deep tray with the oil.','Fry the diced chorizo in a pan until the oil runs, add the sliced garlic and herbs, then pour in the stock cube dissolved in 200ml hot water and the vinegar.','Season the chicken with the paprika, sit it on the vegetables and pour the chorizo stock over. Cover with foil and bake for 35 minutes.','Take the foil off and bake for another 20 minutes, until the chicken is golden and cooked through and the vegetables are tender.','Serve with a spoonful of yoghurt, the chopped chilli, crushed almonds and a squeeze of lemon.']::text[],array['eggs','milk','nuts','peanuts','sulphites']::text[],'live','idea: Jamie Oliver',false,'21be9b3edb64dcb3',212,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
