insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-fajita-pasta','Chicken Fajita Pasta','dinner','🌶️',4,542,42,68,13,array['Cook the pasta to the packet instructions, saving a mug of the cooking water, then drain.','Toss the sliced chicken in half the fajita seasoning and fry in half the oil for 5 to 6 minutes until golden and nearly cooked, then lift out.','Fry the sliced onion with the rest of the seasoning in the remaining oil for 3 to 4 minutes, then add the peppers and cook for another 3 to 4 minutes.','Return the chicken with the tomato puree and cook for 2 minutes, then stir in the passata, pasta and yoghurt and heat through, loosening with pasta water if needed.','Scatter over the grated cheese and serve. It is also good cold the next day.']::text[],array['gluten','milk','sulphites']::text[],'live','idea: Sainsbury''s recipes',false,'527d89c8e66bdb8f',167,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
