insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-fajitas','Chicken Fajitas','dinner','🫑',2,689,52,72,21,array['Slice the chicken breast into strips and toss in the fajita seasoning. Slice the pepper and onion.','Heat the oil in a large frying pan until hot and fry the chicken for 6 minutes, turning, until golden and cooked through.','Add the pepper and onion and cook for 3 to 4 minutes until softened. Warm the wraps for 30 seconds in a dry pan or the microwave.','Spoon the filling into the warm wraps, scatter over the grated cheddar and serve.']::text[],array['gluten','milk','sulphites']::text[],'live','poc',false,'975c500a9ef5e616',206,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
