insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-fried-rice','Chicken Fried Rice','dinner','🍚',2,512,49,67,7,array['Cook the rice following the pack instructions and spread out to cool. Dice the chicken breast and slice the onion, pepper and spring onion.','Fry the chicken in a little oil for 6 to 8 minutes until golden and cooked through. Scramble the eggs in the same pan for 1 to 2 minutes, then set both aside.','Fry the onion and pepper for 3 minutes, then add the cold rice and garlic and stir-fry for 2 minutes. Add the soy sauce.','Return the chicken and egg to the pan, stir through the teriyaki sauce until piping hot, then top with the spring onion and serve.']::text[],array['eggs','gluten','sesame','soya']::text[],'live','poc',false,'404fabed7c84ff79',198,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
