insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-katsu-curry','Crispy Chicken Katsu Curry','dinner','🍛',2,628,46,87,12,array['Heat the oven to 220C (200C fan). Brush the chicken breasts on both sides with the oil, season and press them into the panko so they are coated all over. Place on a baking tray.','Bake for 20 minutes until golden and cooked through, then rest for 4 to 5 minutes and slice thickly.','Meanwhile cook the rice following the pack instructions, stirring in the sliced spring onions for the last minute. Warm the katsu sauce in a small pan for 5 minutes.','Peel the carrot and cucumber into ribbons and toss with the chopped chilli and a squeeze of lime.','Divide the sliced chicken between two plates, pour over the sauce and serve with the rice, the salad and the rest of the lime in wedges.']::text[],array['gluten','soya']::text[],'live','idea: BBC Good Food',false,'a3889b066643c3d1',233,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
