insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-milanese-pasta','Chicken Milanese Pasta','dinner','🍝',2,662,57,80,14,array['Cut each chicken breast in half through the middle, then flatten the pieces between two sheets of baking paper until thin and even.','Dust the chicken with the flour, dip it in the beaten egg, then press on the breadcrumbs mixed with a pinch of salt and pepper until fully coated.','Fry the chicken in the oil in a frying pan over a medium-high heat for 4 to 5 minutes each side until golden, crisp and cooked through.','Meanwhile cook the spaghetti in salted boiling water to packet instructions, about 10 minutes, then drain and stir through the passata, garlic and herbs for 2 minutes over a low heat.','Divide the spaghetti between two plates, top with the sliced chicken and scatter over the parmesan.']::text[],array['eggs','gluten','milk']::text[],'live','idea: Joe Wicks',false,'fd89dcd9915f703a',199,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
