insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-pepper-harissa-orzo','Chicken, Pepper & Harissa Orzo','dinner','🌶️',4,526,41,62,14,array['Chop the peppers into chunky pieces, slice the garlic, finely chop the sun-dried tomatoes and cut the chicken into 3cm pieces. Crumble the stock cube into 700ml of hot water.','Heat the oil in a large saucepan over a medium heat and cook the peppers for 6 to 8 minutes until starting to soften. Stir in the garlic and orzo for a minute.','Pour in the stock, then add the harissa, sun-dried tomatoes and chicken. Simmer, stirring now and then, for 12 to 15 minutes until the orzo is tender, the liquid has been absorbed and the chicken is cooked through with no pink left. Add a splash of water if it dries out.','Stir in the mascarpone and red wine vinegar and season to taste.','Divide between bowls and serve.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','idea: Mob',false,'b2292c22038190bd',214,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
