insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-pepper-risotto','Chicken and Roast Pepper Risotto','dinner','🍚',2,662,50,74,19,array['Heat the oven to 200C (180C fan). Brown the chicken breasts in a hot pan with a little oil for 3 minutes on each side, then lift onto a foil-lined tray with the sliced pepper and a drizzle of oil.','Roast for 15 to 20 minutes until the pepper is soft and the chicken is cooked through with no pink.','Stir the stock cube into 700ml boiling water with the tomato puree, rice vinegar, honey and chilli flakes. Soften the diced onion in the butter for 4 minutes, then stir in the rice, chopped garlic, paprika and curry powder for 1 minute.','Add the stock a ladle at a time, stirring, for 25 to 30 minutes until the rice is tender and creamy.','Shred the chicken, stir it into the risotto with the roasted pepper and half the grated cheddar, and serve topped with the rest of the cheese and sliced spring onion.']::text[],array['eggs','milk','sulphites']::text[],'live','idea: Gousto',false,'7e1860a3981056fc',228,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
