insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-spinach-lasagne','Chicken & Spinach Lasagne','dinner','🍽️',4,787,53,74,31,array['Heat the oven to 200C (180C fan). Roast the chicken thighs on a tray with a little oil for 18 minutes until cooked through, then shred with two forks.','Soften the chopped onion in the oil, add the garlic, then the tomatoes, puree, oregano and stock cube in 300ml hot water. Simmer for 10 to 15 minutes, then stir in the shredded chicken.','Melt the butter, stir in the flour for a minute, then whisk in the milk gradually until smooth and thick for a white sauce.','Wilt the spinach in a colander with boiling water, rinse and squeeze dry.','Layer the chicken sauce, lasagne sheets and spinach in a dish, finish with white sauce and cheese and bake for 20 to 25 minutes until golden. Rest for 5 minutes before serving.']::text[],array['eggs','gluten','milk']::text[],'live','idea: Gousto',false,'29b008c8ae16d75a',217,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
