insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chicken-tikka-wrap','Chicken Tikka Wrap','lunch','🌯',1,474,42,41,15,array['Toss the chicken pieces with half the yoghurt, the tikka paste and the oil, then cover and chill for at least 30 minutes (overnight is fine).','Heat the grill to high and line a tray with foil. Grill the chicken for 7 to 8 minutes, turning once, until lightly charred and cooked through, then leave to cool a little.','Warm the wrap for a few seconds in the microwave and spread it with the rest of the yoghurt.','Top with sliced tomato, cucumber, coriander and the chicken, roll up tightly, slice in half and serve.']::text[],array['gluten','milk']::text[],'live','idea: Joe Wicks',false,'1e908e7ea992646d',199,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
