insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chilli-pork-brothy-rice','Chilli Pork Brothy Rice','dinner','🍚',2,526,36,67,14,array['Rinse the rice, cover with twice its volume of water, bring to the boil, then cover and simmer on low for 12 minutes. Leave covered off the heat for 10 minutes, then fluff.','Thinly slice the cabbage, garlic and spring onions. Stir-fry the pork mince in half the oil over a medium heat for 5 to 7 minutes until browned and cooked through.','Add the cabbage, five spice, a pinch of salt and pepper and the teriyaki sauce and toss for 2 minutes, then set aside.','In the same pan fry the garlic and most of the spring onions in the rest of the oil for 2 minutes, then add the soy sauce, chilli flakes and the stock cube dissolved in 400ml water. Simmer for 4 minutes and season with the vinegar.','Spoon the rice into bowls, top with the pork, ladle over the broth and scatter with the last spring onions.']::text[],array['eggs','gluten','sesame','soya','sulphites']::text[],'live','idea: Mob',false,'ef8e2b6e1f76d763',133,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
