insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chilli-pork-pasta-bake','Chilli Pork Pasta Bake','dinner','🍝',4,530,37,69,13,array['Heat the oven to 180C (160C fan). Cook the pasta until just tender, then drain.','Fry the chopped onion and pork mince in the oil for about 5 minutes until browned.','Stir in the fajita seasoning, tomatoes, drained beans and sweetcorn, then add 300ml hot water with the stock cube crumbled in. Simmer for a few minutes until slightly thickened.','Stir in the pasta, tip into a baking dish, scatter over the cheese and bake for 15 to 20 minutes until golden.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','idea: Joe Wicks',false,'e140dc1e93e3267c',108,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
