insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chilli-wraps','Chilli Wraps','lunch','🌯',1,654,39,82,17,array['Heat the oil in a frying pan over a medium-high heat and fry the chopped onion and garlic for 3 minutes until starting to soften.','Add the beef mince with the cumin, paprika and chilli flakes and cook for 3 to 4 minutes, breaking it up, until browned and fragrant.','Stir in the chopped tomatoes and kidney beans and simmer for 5 minutes until thick and the mince is cooked through, then season.','Warm the wraps, spoon the chilli into them, top with the coriander and a spoonful of yoghurt, then roll up and serve.']::text[],array['gluten','milk']::text[],'live','idea: Joe Wicks',false,'63e66a24350e5b63',228,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
