insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chinese-chicken-curry','Chinese Chicken Curry','dinner','🍛',4,491,43,69,7,array['Toss the chicken pieces in the cornflour with a little seasoning and set aside.','Fry the chopped onion in half the oil in a wok over a low to medium heat for 5 to 6 minutes, then add the garlic and cook for 1 minute. Stir in the curry powder and ginger and cook for 1 minute more.','Pour in the stock made with the cube and 400ml of hot water, add the soy sauce, bring to a simmer and cook for 20 minutes. Tip the sauce into a blender and blitz until smooth.','Wipe out the pan, then fry the chicken in the remaining oil until browned all over. Pour the sauce back in and simmer for 5 minutes until the chicken is cooked through.','Stir in the peas for the last 3 minutes while you cook the rice following the pack instructions. Serve the curry over the rice.']::text[],array['eggs','gluten','soya']::text[],'live','idea: BBC Good Food',false,'16c4d3fc44945bea',132,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
