insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chorizo-potato-hash-eggs','Chorizo & Potato Hash with Egg','breakfast','🥔',1,492,39,35,22,array['Boil the chopped potatoes for 10 minutes until just tender, then drain and leave to cool. Cooking them ahead helps them crisp.','Fry the diced chorizo in a non-stick pan over a medium heat for 4 to 5 minutes until crisp and the oil has run.','Turn up the heat, add the diced onion and pepper and cook for a couple of minutes, then add the potatoes and cook for 3 to 4 minutes until crisp at the edges.','Add the spinach, chopped chicken and chilli flakes and fry for a couple of minutes, then season.','Meanwhile poach the egg in gently simmering water for 3 minutes until the white is set and the yolk is runny.','Top the hash with the egg, scatter over the coriander and serve.']::text[],array['eggs']::text[],'live','idea: Joe Wicks',false,'6d9603a34c85274e',296,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
