insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('chorizo-seafood-paella','Chorizo and Seafood Paella','dinner','🥘',4,596,36,56,25,array['Fry the halved chorizo in a large lidded sauté pan on a high heat for 2 to 3 minutes, then lift out and pour off most of the oil.','Add the oil and sliced onion, cover and cook for 5 minutes, then add the sliced pepper and cook for 2 to 3 minutes. Stir in the paella rice.','Stir the paprika into 800ml hot water with the crumbled stock cube, pour it over the rice and bring to the boil, then simmer uncovered for 10 minutes, stirring now and then. Cover and cook for 5 minutes.','Stir in the seafood and chorizo, cover and cook for 3 minutes until the seafood is piping hot and cooked through, then add the peas and cook for 2 minutes.','Squeeze over some lemon, leave to stand for 1 minute, then serve with the rest of the lemon in wedges.']::text[],array['crustaceans','eggs','molluscs']::text[],'live','idea: Sainsbury''s recipes',false,'e578a3dcf520d35e',242,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
