insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('creamy-chicken-mushroom-stew','Creamy Chicken & Mushroom Stew','dinner','🍲',4,471,37,44,17,array['Heat the oven to 200C (180C fan). Brown the chicken thighs in the oil in a lidded ovenproof pan.','Add the onion wedges, sliced carrot, garlic and flour and mix well. Pour in 400ml hot water with the stock cube, add the mushrooms and herbs and bring to the boil.','Cover and bake for 40 minutes until the chicken and vegetables are tender. Prick the potatoes and bake on a tray alongside.','Stir the crème fraîche through the stew. Crush the potatoes with the butter and a pinch of salt and serve alongside.']::text[],array['eggs','gluten','milk']::text[],'live','idea: Gousto',false,'4bc22bc8ff511e3a',189,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
