insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('creamy-chicken-pasta','Creamy Chicken Pasta','dinner','🍝',2,564,49,64,14,array['Boil the fusilli in salted water for 10 minutes, then drain, keeping a mugful of the pasta water. Slice the chicken breast into strips.','Fry the chicken in a hot pan for 6 to 8 minutes, turning, until golden and cooked through. Add the chopped garlic for the last minute.','Stir in the crème fraîche and a splash of the pasta water, then the spinach, and cook for 2 minutes until the spinach wilts into a creamy sauce.','Toss the pasta through the sauce, divide between two bowls and finish with grated parmesan.']::text[],array['gluten','milk']::text[],'live','poc',false,'e5c9231d05339f7b',177,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
