insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('creamy-egg-on-toast','Creamy Egg Mash on Toast','breakfast','🥚',1,472,29,47,18,array['Boil the eggs for 8 minutes until the yolks are firm, then drain, cool under cold water and peel.','Halve the eggs and mash the yolks in a bowl with the Greek yoghurt, soft cheese, paprika, salt and pepper until creamy.','Finely chop the egg whites and stir them into the yolk mixture.','Toast the bread, pile the creamy egg on top, scatter over the chilli flakes and serve straight away.']::text[],array['eggs','gluten','milk','soya']::text[],'live','idea: The Happy Foodie',false,'bb21d786f808cb07',117,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
