insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('creamy-pork-mushroom-pasta','Creamy Pork & Mushroom Pasta','dinner','🍄',4,746,38,83,31,array['Heat the oven to 200C (180C fan). Sear the pork steaks in the oil for 2 minutes each side, then roast on a tray for 8 to 10 minutes until cooked through. Cover and rest.','Cook the pasta to the packet instructions and drain.','In the pork pan, soften the chopped onion and garlic for a minute, add the quartered mushrooms for a minute, then the stock cube in 200ml hot water. Simmer for 5 minutes and stir in the crème fraîche and herbs.','Toss the pasta through the sauce, top with sliced pork and grated parmesan.']::text[],array['eggs','gluten','milk']::text[],'live','idea: Gousto',false,'81459bb4e7ceb56d',204,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
