insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('creamy-salmon-pasta-bake','Creamy Salmon Pasta Bake','dinner','🐟',4,637,32,75,25,array['Heat the oven to 180C (160C fan). Wrap the salmon in foil with a drizzle of oil, half the garlic, a squeeze of lemon, salt and pepper, and bake for 15 minutes until cooked through.','Meanwhile boil the fusilli in salted water for 10 to 12 minutes until just tender, then drain.','Soften the sliced leeks in the butter and the rest of the garlic for 5 minutes, stir in the flour, then add the milk a little at a time, stirring, until you have a thick creamy sauce. Stir in the yoghurt and mustard and season well with pepper.','Tip the pasta into an ovenproof dish, flake the salmon over it (check for bones), spoon the creamy leeks over to the edges and scatter with the breadcrumbs.','Bake for 15 minutes until golden on top, then serve in bowls.']::text[],array['fish','gluten','milk','mustard','sulphites']::text[],'live','idea: Sainsbury''s recipes',false,'0f4373b6070ca4f5',249,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
