insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('crispy-chicken-garlic-beans','Crispy Chicken & Garlicky Beans','dinner','🍗',2,437,51,33,12,array['Slice each chicken breast through the middle to make two thin pieces and flatten them with a rolling pin. Press both sides into the breadcrumbs mixed with the grated lemon zest and herbs.','Steam or boil the green beans and broccoli for 5 to 6 minutes until just tender.','Pan-fry the chicken in half the oil for 3 to 4 minutes each side (about 6 minutes in all), until golden and cooked right through.','Warm the drained butter beans in the rest of the oil with the sliced garlic, simmering for 2 minutes, then take off the heat and stir in the yoghurt and a squeeze of lemon.','Serve the chicken on the beans with the greens alongside.']::text[],array['gluten','milk']::text[],'live','idea: Jamie Oliver',false,'8a4dd0905dfc9b71',269,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
