insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('crispy-chicken-spicy-honey-noodles','Crispy Chicken Spicy Honey Noodles','dinner','🍜',2,482,40,60,11,array['Season the chicken thighs with salt. Fry in the oil over a medium heat for 6 minutes, turn, and fry for 5 to 6 minutes more until crisp, golden and cooked through. Lift out and leave to rest.','Slice the spring onion and chilli and stir with half the soy sauce, half the vinegar, half the honey and half the crushed garlic to make a quick topping.','Mix the tomato puree, chilli flakes, the rest of the soy sauce, vinegar, honey and garlic with 4 tablespoons of water for the sauce.','Boil the noodles for 3 minutes, then drain, saving a little cooking water.','Pour the sauce into the chicken pan and bubble for 1 minute, then toss through the noodles with a splash of the cooking water.','Slice the chicken, pile it on the noodles and spoon over the spring onion topping.']::text[],array['eggs','gluten','soya','sulphites']::text[],'live','idea: Mob',false,'599ae78518b2b598',176,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
