insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('crispy-sweet-chilli-beef-noodles','Crispy Sweet Chilli Beef Noodles','dinner','🍜',2,695,50,86,19,array['Cook the noodles in boiling water for 4 minutes, drain and rinse under cold water. Toss the sliced steak in the cornflour with a pinch of salt and pepper until evenly coated.','Heat the oil in a large frying pan or wok over a medium heat and fry the steak for 5 to 6 minutes until crispy and cooked through. Lift it out and keep to one side, leaving the oil in the pan.','Fry the sliced onion and peppers in the same pan for 4 minutes until soft, then add the spring onions, chilli and garlic and cook for 2 minutes more.','Stir in the honey, tomato puree, vinegar and soy sauce with a splash of water and cook for 1 minute until glossy.','Add the noodles and crispy steak and toss for 2 minutes to heat through, then divide between bowls and serve.']::text[],array['eggs','gluten','soya','sulphites']::text[],'live','idea: Morrisons Recipes (Good Food)',false,'2b82b42e309082ac',423,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
