insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('curried-satay-noodles','Curried Satay Noodles','dinner','🍜',2,535,20,72,20,array['Boil the noodles for 4 minutes, then drain and rinse well so the strands stay separate.','Meanwhile heat the oil in a wok over a high heat and stir-fry the pepper, carrots, ginger, garlic and chilli for 5 minutes until softened. Stir in the cumin and curry powder and cook for 30 seconds until fragrant.','Mix the peanut butter and tomato puree with the stock made from the cube and 150ml of hot water until smooth.','Add the drained noodles and peas to the wok and pour in the peanut mixture. Toss everything together, loosening with a splash of water if it is thick.','Squeeze over the lemon juice, toss again and serve.']::text[],array['eggs','gluten','peanuts']::text[],'live','idea: BBC Good Food',false,'eb04b7c5d66d5d07',111,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
