insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('drunken-noodles','Drunken Noodles','dinner','🍜',4,511,34,74,9,array['Soak the rice noodles in boiling water for about 10 minutes, or as the packet says, then drain. Mince the garlic, slice the chilli, onion and peppers, cut the spring onion into 4cm pieces and thinly slice the chicken.','Stir together the fish sauce, oyster sauce, soy sauce, dark soy and honey in a bowl.','Heat the oil in a large wok until very hot and stir-fry the garlic, onion, peppers and chilli for 2 minutes.','Add the chicken and cook for 4 to 5 minutes, stirring, until cooked through with no pink left.','Pour in the sauce, add the noodles and toss until coated, then mix in the spring onion.','Divide between bowls and serve straight away.']::text[],array['fish','gluten','molluscs','soya']::text[],'live','idea: Mob',false,'3c91af2de15eae29',193,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
