insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('easy-butter-chicken','Easy Butter Chicken','dinner','🍛',4,573,37,70,18,array['Mix the Greek yogurt, lemon juice, cumin, paprika and chilli flakes in a bowl. Toss the chopped chicken thighs through it, cover and chill for 30 minutes.','Heat the oil in a large heavy pan and fry the chopped onion, garlic and ginger over a medium heat for 10 minutes until soft.','Stir in the tomato puree and cook for 2 minutes, then pour in the stock made with the cube and 300ml of hot water. Add the marinated chicken and cook for 15 minutes.','Pour in any marinade left in the bowl, simmer for 5 minutes until the chicken is cooked through, and cook the basmati rice following the pack instructions.','Scatter the nuts and coriander over the curry. Serve with the rice.']::text[],array['eggs','milk','nuts','peanuts']::text[],'live','idea: BBC Good Food',false,'4bbe18c90296ad5a',153,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
