insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('healthy-seafood-spaghetti','Healthy Seafood Spaghetti','dinner','🍝',2,520,35,66,15,array['Heat the oil in a large non-stick pan and cook the sliced celery and chopped onion for 10 minutes, stirring now and then, until softened. Meanwhile boil the spaghetti for 10 minutes until al dente.','Stir the chilli flakes, grated garlic, lemon zest and lemon juice into the softened vegetables, then add the tomato puree and cook briefly, stirring all the time.','Drain the spaghetti, keeping a mugful of the cooking water. Add the seafood to the sauce and warm it through for 2 to 3 minutes.','Toss the spaghetti into the sauce with the chopped basil and just enough of the cooking water to loosen it. Season and serve.']::text[],array['celery','crustaceans','gluten','molluscs']::text[],'live','idea: BBC Good Food',false,'8ab619e5f7d134fa',238,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
