insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('herby-mayo-chicken-sandwich','Herby Mayo Chicken Sandwich','lunch','🥪',1,439,34,51,10,array['Finely chop the spring onions and coriander and stir them into the mayonnaise with a good squeeze of lemon juice, salt and pepper.','Toast the bread and let it cool a moment. Slice the chicken, cucumber and tomatoes, and season the tomatoes with a pinch of salt.','Spread herby mayonnaise on both slices of toast. Layer the cucumber, chicken, tomatoes and salad leaves on one, close the sandwich, press down gently and serve cut in half.']::text[],array['eggs','gluten','mustard','soya']::text[],'live','idea: Mob',false,'7258f4ad5cc94f57',276,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
