insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('honey-and-soy-chicken','Honey & Soy Chicken','dinner','🍯',2,489,44,76,3,array['Cook the rice following the pack instructions. Slice the chicken breast into strips and chop the garlic.','Fry the chicken in a hot pan for 6 to 8 minutes, turning, until golden and cooked through. Add the garlic for the last minute.','Stir the soy, honey and 100ml water together and pour into the pan. Mix a teaspoon of cornflour with a splash of cold water and stir it in. Simmer for 2 minutes until glossy.','Steam the broccoli for 4 minutes. Divide the rice and broccoli between two plates, spoon over the chicken and every drop of the sauce and serve.']::text[],array['gluten','soya']::text[],'live','poc',false,'fa8f3e78ac1789f8',177,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
