insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('honey-pork-noodles','Honey Pork Noodles','dinner','🍯',2,683,40,67,30,array['Heat the grill to high. Mix the honey, soy sauce, five spice, paprika and oil in a bowl and turn the sliced pork in it.','Lay the pork on a foil-lined tray and pour the leftover marinade into a small pan. Grill the pork for 8 to 10 minutes, turning, until lightly charred and cooked through.','Boil the spare marinade for about 3 minutes until thick and glossy and spoon it over the pork.','Boil the noodles for 3 minutes, adding the stir-fry vegetables for the last 2, then drain and serve with the pork.']::text[],array['eggs','gluten','soya']::text[],'live','idea: Joe Wicks',false,'0ab113556849e7d2',239,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
