insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('honey-sriracha-chicken-bowls','Honey Sriracha Chicken Bowls','dinner','🍗',4,525,43,73,8,array['Cook the rice following the packet, about 12 minutes, then drain and keep covered.','Finely chop the chilli and stir it with the tomato puree, honey, soy sauce and a splash of water for a quick sriracha-style sauce. Slice the spring onions and garlic, keeping a handful of the spring onions back.','Heat the oil in a large frying pan over a medium-high heat. Cut the chicken thighs into bite-size pieces and fry for 8 to 10 minutes, turning, until golden.','Add the garlic and most of the spring onions and cook for 5 minutes until soft and fragrant.','Pour in the sauce and bubble for 3 to 4 minutes until sticky and the chicken is cooked through with no pink left.','Spoon the rice into bowls, top with the chicken and scatter over the reserved spring onions.']::text[],array['gluten','soya']::text[],'live','idea: Mob',false,'2f3e2a0b32a1d719',176,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
