insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lamb-meatball-pitta-wraps','Lamb Meatball Pitta Wraps','dinner','🥙',4,501,26,36,26,array['Heat the oven to 190C (170C fan). Mix the lamb mince with the oregano and sesame seeds and roll into 16 small meatballs.','Fry the meatballs in the oil for 4 minutes until browned all over, then move to a baking tray. Sprinkle the pittas with water and wrap in foil.','Bake the meatballs and pittas together for 6 to 8 minutes until the lamb is cooked through and the bread is warm.','Meanwhile toast the chopped nuts in a dry pan for 2 minutes and cool. Toss the sliced onion and quartered tomatoes with the vinegar and honey, and ripple the harissa through the yoghurt.','Split the pittas and fill with the meatballs, tomato salad, harissa yoghurt and houmous, then scatter with the coriander and nuts and serve.']::text[],array['gluten','milk','nuts','peanuts','sesame','sulphites']::text[],'live','idea: Sainsbury''s recipes',false,'78784bbc61090727',162,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
