insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lamb-moussaka','Lamb Moussaka','dinner','🍆',4,573,30,51,28,array['Heat the oven to 160C (140C fan). Heat 2 teaspoons of the oil in a large pan and fry the chopped onions and garlic for 5 minutes until soft. Turn up the heat, add the lamb mince and fry for 5 minutes until browned.','Stir in the cinnamon, oregano and tomato puree and cook for 1 minute. Add the chopped tomatoes, the stock cube and 150ml boiling water and simmer for 20 minutes until thick and the lamb is cooked through. Season.','Meanwhile, heat a griddle pan until very hot. Slice the aubergines lengthways into 1cm slices, brush with the remaining oil and griddle for 2 minutes each side in batches until golden.','Melt the butter in a pan, whisk in the flour and cook for 1 minute. Gradually whisk in the milk and simmer for 2 minutes until thick. Off the heat, whisk in the parmesan, nutmeg and then the beaten egg.','Layer half the aubergine, all the lamb, then the rest of the aubergine in an ovenproof dish and pour over the sauce. Bake for 35 to 40 minutes until risen and golden. Boil the potatoes for 15 minutes in the meantime, drain, rest the moussaka for 5 minutes, then serve with the potatoes.']::text[],array['eggs','gluten','milk']::text[],'live','idea: Joe Wicks',false,'51ae9f6cc992a0c6',243,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
