insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lasagne','Lasagne','dinner','🍜',2,755,53,87,21,array['Heat the oven to 200C (180C fan). Soften the chopped onion and grated carrot in a pan for 5 minutes, then add the beef mince and cook for 8 minutes, breaking it up, until browned and cooked through.','Stir in the chopped tomatoes and puree with a splash of water and simmer for 15 minutes until thick and rich. Season well.','For the cheese sauce, whisk the cornflour into the cold milk in a small pan, heat gently for 4 to 5 minutes, stirring, until thickened, then stir in half the cheddar.','Layer the lasagne sheets, beef ragu and cheese sauce in an ovenproof dish, finishing with a layer of sauce, and scatter over the remaining cheddar.','Bake for 35 to 40 minutes until golden and bubbling, then rest for 5 minutes and serve in generous slices.']::text[],array['eggs','gluten','milk']::text[],'live','poc',false,'ae5b65141de504fe',272,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
