insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lean-beef-and-veg-stew','Lean Beef and Veg Stew','dinner','🍲',2,510,35,67,9,array['Heat the oil in a large pan and fry the chopped onion for 5 minutes until soft. Add the beef mince and cook for 6 minutes, breaking it up, until browned and cooked through.','Stir in the puree and cook for 1 minute, then add the diced potatoes and carrots, the chopped tomatoes and 200 ml water.','Cover and simmer for 30 minutes, stirring now and then, until the potatoes and carrots are tender.','Stir in the drained kidney beans and cook for 5 minutes until hot. Season to taste, then ladle into bowls and serve.']::text[],array[]::text[],'live','table-plan',false,'615d7b585a126c19',230,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
