insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lean-cottage-pie','Lean Cottage Pie','dinner','🥧',2,609,41,78,16,array['Heat the oven to 200C (180C fan). Heat the oil in a large pan and fry the chopped onion for 5 minutes until soft.','Add the beef mince and cook for 8 minutes, breaking it up, until browned and cooked through. Stir in the grated carrot, peas and passata and simmer for 15 minutes until thick.','Meanwhile, peel and chop the potatoes, boil for 15 minutes until tender, then drain and mash with the butter and a little salt and pepper.','Spoon the mince into an ovenproof dish, top with the mash and rough it up with a fork. Bake for 20 minutes until golden on top.','Rest for 5 minutes, then spoon onto warm plates and serve.']::text[],array['milk']::text[],'live','table-plan',false,'25aff4692fab7c56',255,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
