insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('lemon-pork-with-sweet-potato','Lemon Pork with Sweet Potato','dinner','🥩',2,590,37,46,30,array['Heat the oven to 200C (180C fan). Toss the diced sweet potato in half the oil with salt and pepper, spread on a tray and roast for 30 minutes, turning once, until soft and golden.','Rub the pork steaks with the herbs, the juice of the lemon and the remaining oil, and leave for 5 minutes.','Fry the pork in a hot pan for 5 to 6 minutes each side until golden and cooked through with no pink inside, then rest for 3 minutes.','Steam or boil the broccoli florets for 4 minutes until just tender. Serve the pork on the roasted sweet potato with the broccoli alongside.']::text[],array[]::text[],'live','table-plan',false,'43ddfef54b12c690',245,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
