insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('light-chicken-and-chickpea-curry','Light Chicken and Chickpea Curry','dinner','🍛',2,555,52,61,10,array['Cook the rice following the packet instructions and keep warm. Heat the oil in a large pan and fry the sliced onion for 5 minutes until soft.','Add the diced chicken and cook for 5 minutes, turning, until sealed and lightly golden on all sides.','Stir in the tikka paste for 1 minute, then add the drained chickpeas and passata. Simmer for 12 minutes until the chicken is cooked through with no pink inside.','Stir in the spinach for 1 to 2 minutes until wilted, season to taste, then spoon over the rice and serve.']::text[],array[]::text[],'live','table-plan',false,'0cfc3ec8c0d7ff0f',221,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
