insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('malaysian-coconut-chicken-and-rice','Malaysian Coconut Chicken with Pickled Cucumber','dinner','🥥',2,640,43,65,25,array['Slice the cucumber finely and mix with the rice vinegar, half the honey and a pinch of salt; set aside to pickle. Put the basmati rice in a lidded pot with 300ml cold water, bring to the boil, then cover and cook on very low for 10 to 12 minutes.','Heat half the oil in a wide lidded pan and brown the chicken thighs with half the curry powder, salt and pepper for 4 to 5 minutes each side.','Meanwhile blitz half the chilli with the onion, nuts, ginger, garlic, soy, the rest of the curry powder, oil and honey into a chunky paste. Stir it into the chicken and cook for 5 minutes until fragrant.','Add the juice of the lime and 100ml water, cover and cook for 10 minutes until the chicken is cooked through, then pour in the coconut milk and cook for 1 minute.','Pull the chicken into chunks with two forks. Serve with the rice and pickled cucumber, scattered with the remaining chilli sliced into rounds.']::text[],array['gluten','nuts','peanuts','soya','sulphites']::text[],'live','idea: Gousto',false,'24ca03f2c750e09e',227,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
