insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('marry-me-chicken-and-orzo','Marry Me Chicken & Orzo','dinner','🍗',4,597,44,49,26,array['Heat the oil and butter in a large lidded pan over a medium heat. Cut the chicken into small pieces, add to the pan and fry for 10 to 12 minutes, turning, until browned and cooked through.','Sprinkle over the paprika, oregano, mixed herbs and chilli flakes. Stir in the garlic and chopped sun-dried tomatoes and cook for 2 minutes.','Add the orzo, crumble in the stock cube and pour in 650ml hot water. Cover and cook for 12 minutes, stirring often, until the orzo is almost tender, adding a splash of water if it looks dry.','Stir in the spinach, lemon zest and juice, mascarpone and parmesan and cook for 2 to 3 minutes until the spinach has wilted and the sauce is creamy. Scatter with torn basil and serve.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','Morrisons (Good Food)',false,'69909b4fff225c7a',238,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
