insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('marry-me-chicken-loaded-fries','Marry Me Chicken Loaded Fries','dinner','🍟',2,540,45,53,18,array['Cut the potatoes into skinny chips and microwave them on medium-high for 7 minutes until just soft. Toss with half the oil, the paprika, mixed herbs, salt and pepper.','Oven method: heat the oven to 220C (200C fan), spread the chips on a large tray and roast for 30 minutes, turning halfway, until golden. In an air fryer, cook at 190C for 20 minutes instead, shaking halfway.','Dice the chicken and fry it in the remaining oil over a medium heat for 7 minutes until golden and cooked through. Add the crushed garlic and cook for 2 minutes.','Stir in the oregano, red pesto, soft cheese and 100ml water, then simmer gently for 3 minutes into a creamy sauce. Season to taste.','Pile the chips into bowls and spoon the creamy marry me chicken over the top.']::text[],array['eggs','milk','nuts']::text[],'live','idea: Mob',false,'3c1d659266e764bb',176,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
