insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('marry-me-chicken-pasta-bake','Marry Me Chicken Pasta Bake','dinner','🍝',2,603,51,72,13,array['Cook the fusilli in boiling salted water for 10 to 12 minutes until al dente. Scoop out a mug of the pasta water, then drain.','Halve the tomatoes and shred the cooked chicken. Heat the grill to high.','Blend the cottage cheese, pesto, tomato puree, passata, garlic, chilli flakes and paprika until smooth, loosening with a splash of pasta water.','Tip the pasta, chicken and tomatoes into an ovenproof dish, pour over the sauce and stir until coated, adding more pasta water if it looks dry.','Grate the parmesan over the top and grill for 8 to 10 minutes until golden and bubbling, then serve.']::text[],array['eggs','gluten','milk','nuts']::text[],'live','idea: Mob',false,'7e5c9f8c664d763c',323,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
