insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('marry-me-spaghetti-meatballs','Marry Me Spaghetti & Meatballs','dinner','🍝',2,710,46,72,28,array['Finely dice the onion and crush the garlic. Mix the mince with the oregano, mixed herbs, salt and pepper and roll into 12 small meatballs.','Fry the meatballs in half the oil over a medium heat for 10 minutes, turning, until browned and cooked through. Lift them onto a plate.','Boil a large pan of water with the stock cube dissolved in it and cook the spaghetti for 10 minutes, saving a mug of the water before draining.','Fry the onion and garlic in the meatball pan with the rest of the oil for 7 minutes until soft, then stir in the pesto, tomato puree and crème fraîche with a ladle of pasta water. Return the meatballs and simmer for 3 minutes.','Toss the drained spaghetti through the sauce and serve topped with grated parmesan.']::text[],array['eggs','gluten','milk','nuts']::text[],'live','idea: Mob',false,'0f54a036e6a4f463',265,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
