insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('meatball-cowboy-pie','Meatball Cowboy Pie','dinner','🤠',4,640,36,69,24,array['Heat the oven to 200C (180C fan). Peel and chop the potatoes and boil for 15 minutes.','Squeeze the sausagemeat out of the skins and mix with the mince, half the grated onion, breadcrumbs, egg and herbs. Roll into about 16 small meatballs and brown in half the oil.','Soften the remaining chopped onion and garlic in the rest of the oil, then add the baked beans and BBQ sauce and simmer for 3 minutes.','Put the meatballs in an ovenproof dish and pour the beans over. Mash the potatoes with the butter and milk, spread on top and sprinkle with cheese.','Bake for 25 to 30 minutes until golden, then serve with peas or greens.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','idea: Morrisons / Good Food',false,'27a3b59ab85078d0',169,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
