insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('middle-eastern-meatball-wraps','Middle Eastern Meatball Wraps','dinner','🌯',2,371,26,38,12,array['Mix the beef mince with the cumin and a pinch of salt and roll into 10 small meatballs, then flatten them slightly.','Heat the oil in a large non-stick frying pan and cook the meatballs for 8 minutes, turning, until browned and cooked through.','Add the sliced peppers and cook over a high heat for 5 minutes until softened and lightly charred.','Stir a squeeze of lemon into the yoghurt. Warm the wraps for 20 seconds in the microwave and pile the spinach and torn coriander into each.','Top with the meatballs and peppers, spoon over the lemony yoghurt and serve rolled up.']::text[],array['gluten','milk']::text[],'live','idea: Sainsbury''s recipes',false,'0fe561082fb4bf66',198,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
