insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('moroccan-chicken-couscous','Moroccan Chicken Couscous','dinner','🍋',4,492,46,51,12,array['Mix the chicken with the oil, half the garlic, cumin, paprika, oregano, curry powder, the zest of the lemon and half its juice, plus salt and pepper. Air fry at 200C for 14 to 18 minutes until cooked through, shaking halfway. Or heat the oven to 220C (200C fan) and roast on a tray for 20 to 25 minutes until golden and cooked through with no pink inside.','Meanwhile put the couscous in a heatproof bowl, pour over 300ml boiling water mixed with the stock cube, cover and leave for 8 to 10 minutes.','Stir the Greek yoghurt with the remaining garlic and lemon juice. Chop the sun-dried tomatoes, dice the cucumber and tear the basil.','Rest the chicken for 3 minutes and slice. Fluff the couscous with a fork, stir in the tomatoes, cucumber, basil and vinegar, then serve topped with the chicken and the garlic yoghurt.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','idea: Mob',false,'d3954ca444fc6e67',177,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
