insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('one-pan-gnocchi-bake','One-Pan Gnocchi Bake','dinner','🥘',4,441,40,47,9,array['Heat the oil in a large, deep frying pan over a medium-high heat. Add the gnocchi and diced chicken breast and fry for 5 minutes, turning, to brown the outside.','Stir in the chopped tomatoes, sliced mixed peppers and trimmed green beans, then add a good splash of water.','Simmer for 6 minutes until the gnocchi is soft and the chicken is cooked through with no pink inside.','Heat the grill to high. Scatter the mozzarella over the pan and grill for 3 minutes until melted and golden, then serve straight from the pan.']::text[],array['gluten','milk']::text[],'live','idea: Joe Wicks',false,'844f74a950222a8d',223,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
