insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('pad-see-ew-chicken-noodles','Pad See Ew Chicken Noodles','dinner','🥢',2,736,51,87,21,array['Slice the chicken and marinate it with half the fish sauce and a pinch of salt for 10 minutes. Mince the garlic and cut the broccoli into 3cm pieces. Soak the noodles in boiling water until soft, drain and toss with the dark soy.','Mix the oyster sauce, soy sauce, honey and the rest of the fish sauce for the noodle sauce. Stir the chopped chilli and a little rice vinegar together for a dipping sauce.','Heat half the sesame oil in a large pan over a high heat and sear the chicken for 2 minutes each side until golden. Remove it from the pan.','Add the rest of the oil and fry the garlic for 30 seconds. Scramble the eggs in big chunks, then add the broccoli, noodles and half the sauce and toss for 2 minutes.','Return the chicken, adding more sauce, and cook for 2 to 3 minutes until charred in places and the chicken is cooked through.','Divide between bowls and top with sliced cucumber, chopped nuts and the dipping sauce.']::text[],array['eggs','fish','gluten','molluscs','nuts','peanuts','sesame','soya','sulphites']::text[],'live','idea: Mob',false,'2e43a6a325f1b6f3',311,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
