insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('paprika-chicken-chorizo-wrap','Paprika Chicken & Chorizo Toasted Wrap','lunch','🌯',1,567,49,39,23,array['Dice the chicken into 1 to 2cm chunks and the onion finely, and cut the chorizo into small pieces.','Put the onion, chorizo and chicken in a non-stick pan over a medium heat, sprinkle over the paprika and fry for about 10 minutes until the onion is soft and the chicken is cooked through.','Stir in the tomato puree, take off the heat and mix in the soft cheese and grated cheddar.','Warm the wrap in the microwave, spoon most of the filling into the middle and fold in the sides and roll up, tucking the end under.','Put the wrap back in the hot pan, spread the rest of the filling on top and cook for a few minutes each side until golden and crisp. Leave for 5 minutes, then cut in half and serve.']::text[],array['gluten','milk']::text[],'live','idea: Mob',false,'3c211b0a0552f557',175,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
