insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('parmesan-chicken-caesar-wrap','Parmesan Chicken Caesar Wrap','lunch','🌯',1,524,42,36,23,array['Slice the chicken into thin strips and toss with the mixed herbs, salt and pepper. Roughly chop the salad leaves and finely grate the parmesan and cheddar.','Heat the oil in a non-stick pan over high heat and fry the chicken for 5 to 6 minutes, turning once, until golden and cooked through.','Meanwhile stir the mayonnaise, vinegar, crushed garlic and a splash of water into a dressing, then toss the salad in it.','Warm the wrap in the microwave for 10 to 15 seconds. Layer the chicken, dressed salad, parmesan and cheddar down the middle, fold in the sides and roll up tightly.','Return the wrap to the pan over a medium heat for 2 to 3 minutes, turning once, until golden and crisp, then serve.']::text[],array['eggs','gluten','milk','mustard','sulphites']::text[],'live','idea: Mob',false,'49624a93eb9ac561',194,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
