insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('salmon-and-veg-parcels','Salmon and Veg Parcels','dinner','🐟',2,418,30,33,20,array['Heat the oven to 200C (180C fan). Slice the potatoes and boil them for 8 minutes, then drain. Cut the broccoli into florets.','Tear off two large squares of foil. Divide the potatoes, broccoli and salmon between them.','Drizzle with the oil, squeeze over the lemon, season and fold the foil over to seal each parcel.','Bake on a tray for 18 minutes until the salmon flakes and the potatoes are tender. Open carefully and serve in the parcels.']::text[],array['fish']::text[],'live','table-plan',false,'ee6819f489e3dfce',321,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
