insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('salt-and-pepper-chicken','Salt & Pepper Chicken','dinner','🍗',2,529,47,74,7,array['Dice the chicken and toss it in the cornflour, five spice, salt and plenty of black pepper. Slice the pepper, onion and chilli, and chop the spring onions.','Heat the oil in a large frying pan or wok and fry the chicken for 6 to 8 minutes, turning, until crisp, golden and cooked through. Lift out onto a plate.','Stir-fry the pepper, onion and chilli in the same pan for 4 to 5 minutes until just soft.','Cook the rice following the pack instructions. Beat the eggs, stir them into the hot rice in the pan and cook for 2 minutes until set.','Return the chicken to the pan, toss everything together, scatter over the spring onions and serve.']::text[],array['eggs']::text[],'live','poc',false,'1de9a20b0c7c1ac9',221,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
