insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sausage-and-mash','Sausage and Mash','dinner','🌭',2,777,38,77,37,array['Heat the grill to high. Grill the sausages for 20 to 25 minutes, turning often, until golden and cooked through with no pink inside.','Peel and chop the potatoes and boil them in salted water for 15 to 20 minutes until tender. Boil the peas for 3 minutes in the last part of the cooking.','Drain the potatoes and mash with the butter, the milk, salt and pepper until smooth.','Slice the onion and soften it in the oil for 8 minutes, then add a splash of hot stock and bubble for 2 minutes for a quick gravy.','Divide the mash between two plates and serve with the sausages, peas and onion gravy.']::text[],array['eggs','gluten','milk','sulphites']::text[],'live','table-plan',false,'f863d9511c15c22e',135,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
