insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sausage-pepper-rice-stew','Sausage, Pepper & Rice Stew','dinner','🌭',2,643,25,86,23,array['Brown the sausages in the oil in a wide, deep pan for 10 minutes, turning, then lift them out and cut each into 3 or 4 chunks. Meanwhile cook the rice to the packet instructions, drain and keep covered.','In the same pan, cook the chopped onion, celery, pepper, garlic and paprika with the chopped chilli, covered, for 10 to 15 minutes until soft.','Sprinkle over the flour and stir, then add the tomatoes, vinegar, sausage chunks and the stock cube dissolved in 350ml hot water, and bring to the boil.','Squash the tomatoes into the sauce and simmer for 10 minutes until thick.','Serve the stew over the rice with sliced spring onions.']::text[],array['celery','eggs','gluten','sulphites']::text[],'live','idea: Jamie Oliver',false,'d7a27911eed61f35',167,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
