insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('singapore-noodles-with-prawns','Singapore Noodles with Prawns','dinner','🍜',2,463,28,50,17,array['Put the noodles in a bowl, cover with boiling water and leave for 3 minutes, then drain and rinse under cold water. Slice the onion and pepper, chop the chilli, crush the garlic and cut the green beans into thirds.','Heat the oil in a wok or large frying pan until very hot. Add the onion, garlic and chilli and stir fry for 2 minutes, then add the curry powder and fry for 1 minute.','Add a splash of water, then the green beans and pepper, and stir fry for 4 to 5 minutes until just tender. Add the spinach and let it wilt.','Add the cooked prawns and heat them through for 2 minutes, then add the noodles and crushed nuts and toss everything together.','Take off the heat, splash over the soy sauce and serve in two bowls.']::text[],array['crustaceans','eggs','gluten','nuts','peanuts','soya']::text[],'live','idea: Joe Wicks',false,'5d4cb873d6cd5bc9',378,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
