insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spaghetti-bolognese','Spaghetti Bolognese','dinner','🍝',2,541,39,73,10,array['Finely chop the onion, carrots and pepper. Fry the mince in a large pan over a high heat for 5 minutes, breaking it up, until browned all over.','Add the chopped vegetables and the garlic and cook for 5 minutes until softened.','Stir in the chopped tomatoes, puree and herbs with salt and pepper. Simmer gently for 20 minutes, stirring now and then, until the mince is cooked through and the sauce is thick.','Meanwhile cook the spaghetti in boiling salted water for 10 to 12 minutes, then drain.','Divide the spaghetti between two bowls, spoon over the bolognese and scatter with the parmesan.']::text[],array['gluten','milk']::text[],'live','poc',false,'0c43f0c39e8074ac',258,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
