insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spanish-chicken-stew','Spanish Chicken Stew','dinner','🥘',4,543,35,67,17,array['Heat half the oil in a large saucepan, season the chicken thighs and brown them for 7 to 8 minutes, turning once, then lift out onto a plate.','Add the rest of the oil to the pan with the chopped pepper, onion and garlic and fry for 8 minutes until lightly golden. Pour in the vinegar and cook for 1 minute.','Return the chicken to the pan with the smoked paprika and the stock made with the cube and 400ml of hot water. Bring to the boil, then simmer for 15 minutes until the chicken is cooked through.','Cook the rice following the pack instructions while the stew simmers.','Scatter the nuts over the stew and serve with the rice.']::text[],array['eggs','nuts','peanuts','sulphites']::text[],'live','idea: BBC Good Food',false,'d7d3f30b88f5d23c',148,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
