insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spanish-shakshuka','Spanish-Style Shakshuka','breakfast','🍳',1,564,33,41,28,array['Heat the oil in a small frying pan over a medium heat, add the chopped chorizo and fry gently for 3 to 4 minutes.','Add the sliced onion and pepper and fry for 5 minutes until softened.','Stir in most of the paprika, the cumin and the tomato puree, fry for a minute, then add a splash of water.','Pour in the tomatoes, bring to a simmer and cook for 8 to 10 minutes until reduced slightly, then season.','Make two wells in the sauce and crack an egg into each. Cover and cook gently for 3 to 4 minutes until the whites are set and the yolks still runny.','Spoon over the yoghurt, finish with a pinch of paprika and serve with two slices of toasted bread.']::text[],array['eggs','gluten','milk','soya']::text[],'live','idea: Joe Wicks',false,'22aa7311b2f6cd8e',221,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
