insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spiced-chicken-rice-traybake','Spiced Chicken & Rice Traybake','dinner','🍗',4,565,45,73,13,array['Heat the oven to 180C (160C fan). Cut the onions and peppers into chunky wedges and tip them into a large roasting tray with half the oil.','Rub the chicken with the paprika, cumin and chilli flakes, sit it on top of the veg and roast for 30 minutes until the veg is soft and the chicken is golden and cooked through.','Take the tray out, pour the rice around the chicken with 600ml boiling water, slice the sweetcorn into rounds and poke it in, then stir.','Cook for 20 minutes until the rice and chicken are tender, then turn the oven up to 200C (180C fan) for 5 minutes for a crispy top.','Serve with a spoonful of yoghurt on each portion.']::text[],array['milk']::text[],'live','idea: Jamie Oliver',false,'18a38960d2fc9cf9',215,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
