insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spiced-turkey-shawarma-rice-bowl','Spiced Turkey Shawarma Rice Bowl','dinner','🥙',2,583,41,61,20,array['Heat the oven to 210C (190C fan). Cut the onion into wedges, toss with the tomatoes and half the oil on a tray, and roast for 20 to 25 minutes until soft and lightly charred at the edges.','Meanwhile, boil the rice for 12 minutes, then drain. Fry the turkey mince in the rest of the oil over a medium-high heat for 10 minutes, breaking it up, until golden and crisp.','Stir the cumin, paprika, chilli flakes, tomato puree and half the grated garlic into the mince and fry for 5 minutes until fragrant and cooked through.','Mix the yoghurt with the remaining grated garlic, the juice of half the lemon and a pinch of salt. Slice the cucumber, chop the coriander and stir both through the roasted onion and tomatoes with a squeeze of lemon.','Divide the rice between two bowls, top with the roasted salad and spiced mince, and spoon over the garlic yoghurt.']::text[],array['milk']::text[],'live','idea: Mob',false,'ced375d9f2e0f954',256,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
