insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spicy-gochujang-beef-pasta','Spicy Gochujang Beef Pasta','dinner','🍝',4,505,32,75,11,array['Finely dice the onion and ginger, crush the garlic and thinly slice the chilli and spring onions, keeping the chilli and spring onions back for the top.','Cook the fusilli in boiling salted water following the packet, about 10 minutes. Save a mugful of the cooking water before draining.','Heat the oil in a large pan over a high heat and brown the mince in a thin layer for 5 minutes, breaking it up, until cooked through. Lift out and keep the juices in the pan.','Turn the heat to medium and soften the onion, garlic and ginger for about 7 minutes. Return the beef and stir in the tomato puree, gochujang, soy sauce and honey with a couple of ladles of pasta water. Simmer for 2 minutes.','Add the pasta and sesame oil, loosening with more water if needed, and finish with a squeeze of lime juice.','Divide between bowls and top with the spring onions, chilli and sesame seeds.']::text[],array['gluten','sesame','soya']::text[],'live','idea: Mob',false,'1e7ab1c0bd4abdd1',204,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
