insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spicy-soy-chicken-and-cabbage','Spicy Soy Chicken & Cabbage','dinner','🥬',2,560,44,70,13,array['Start the rice following the pack instructions, about 12 minutes. Cut the chicken into 3cm pieces, chop the cabbage into large pieces and finely chop the garlic and chilli.','Heat the oil in a wok over a high heat. Season the chicken and fry for 8 to 10 minutes until golden and cooked through, add the garlic and chilli for 2 minutes, then lift everything out.','Fry the cabbage in the hot wok for 5 minutes until charred but still crunchy.','Return the chicken, add the soy sauce and honey and bubble for 2 to 3 minutes until slightly reduced.','Spoon the chicken and cabbage over the rice with the pan juices and scatter with coriander.']::text[],array['gluten','soya']::text[],'live','idea: Mob',false,'2a12619d5f6959a5',170,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
