insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spinach-and-mushroom-frittata','Spinach and Mushroom Frittata','lunch','🍳',1,350,26,2,26,array['Slice the mushrooms, halve the tomatoes and beat the eggs with salt and pepper.','Heat the oil in a small ovenproof frying pan and soften the mushrooms for 3 minutes. Add the spinach and tomatoes and stir for 1 minute until the spinach wilts.','Heat the grill to high. Pour the eggs into the pan, scatter over the cheese and cook over a low heat for 4 to 5 minutes until the base is set.','Put the pan under the grill for 2 minutes until the top is golden and set. Slide onto a plate and serve.']::text[],array['eggs','milk']::text[],'live','table-plan',false,'1f5c62b34293ae79',175,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
