insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('spinach-feta-white-bean-pan','Spinach, Feta & White Bean Pan','dinner','🫘',2,568,30,57,23,array['Slice the spring onions and garlic. Soften them in the oil with a pinch of salt in a large lidded frying pan over a medium heat for 5 minutes.','Tip in the butter beans with their liquid, then add the spinach a handful at a time, letting each handful wilt for about 2 minutes.','Turn the heat down, stir in the lemon zest and crumble in most of the feta until creamy, adding a splash of hot water if it needs more sauce. Do not let it boil.','Cover and warm through for 3 minutes while you toast the pittas.','Top with torn coriander, black pepper and the last of the feta and serve from the pan with the warm pittas.']::text[],array['gluten','milk']::text[],'live','idea: Mob',false,'ed396b6673f4bc11',211,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
