insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('steak-and-chips','Steak and Chips','dinner','🥩',2,806,58,80,27,array['Heat the oven to 220C (200C fan). Spread the chips on a large tray and bake for 25 minutes, turning once, until golden and crisp.','Take the steaks out of the fridge, pat dry and season well. Slice the mushrooms. Heat the oil in a heavy frying pan until very hot.','Fry the steaks for 2 to 3 minutes each side for medium, adding the butter for the last minute and spooning it over. Rest on a plate for 3 minutes.','Fry the mushrooms in the pan juices for 4 minutes until golden. Boil the peas for 3 minutes and drain.','Slice the steak and serve with the chips, mushrooms and peas.']::text[],array['milk']::text[],'live','table-plan',false,'bb1a1fa1deb30e29',525,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
