insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('steak-and-eggs-potatoes','New York-Style Steak & Eggs','breakfast','🥩',1,484,45,26,23,array['Boil the diced potatoes in salted water for 5 minutes, drain well and leave them to steam dry for 2 minutes.','Heat half the oil in a frying pan and fry the chopped onion and pepper for 5 minutes until soft, then set aside. Fry the potatoes in the same pan for 5 to 6 minutes until crisp, return the onion and pepper, toss and season.','Meanwhile heat a griddle or frying pan until very hot, season the steak and cook it for 3 minutes on each side, or longer until cooked to your liking. Rest it for a few minutes.','Wipe out the pan, heat the rest of the oil over a medium heat and fry the eggs for 3 minutes until the whites are set and the yolks still runny.','Serve the sliced steak with the potato mixture and fried eggs.']::text[],array['eggs']::text[],'live','idea: Joe Wicks',false,'88163aae7f0b8e10',415,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
