insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('steak-chimichurri-chickpea-salad','Steak & Chimichurri Chickpea Salad','dinner','🥗',2,482,43,22,22,array['Take the steaks out of the fridge, pat them dry, and season generously with salt. Drain and rinse the chickpeas and halve the tomatoes.','Finely chop the coriander and chilli and whisk in a large bowl with the grated garlic, chilli flakes, oregano, vinegar and 20g of the oil. Season, then stir in the chickpeas and tomatoes.','Heat a heavy frying pan until very hot with the rest of the oil. Sear the steaks, pressing down, for 2 minutes, then turn and cook for 1 to 2 minutes more. Rest for 10 minutes, then slice.','Toss the spinach through the chickpeas, top with the sliced steak and spoon over any resting juices.']::text[],array['sulphites']::text[],'live','idea: Mob',false,'90bbeb4206d96dfa',424,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
