insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('steak-night','Steak Night','dinner','🥩',2,681,54,60,25,array['Heat the oven to 220C (200C fan). Spread the crispy potato slices on a tray and bake for 20 minutes, turning once, until golden.','Take the steaks out of the fridge, pat dry with kitchen paper and season well with salt and pepper.','Heat the oil in a heavy frying pan until very hot and sear the steaks for 3 to 4 minutes each side, then rest on a plate for 3 minutes.','Steam or boil the green vegetable medley for 5 minutes until tender.','Slice the steaks and serve with the potato slices and green vegetables.']::text[],array['gluten','milk']::text[],'live','poc',false,'f3399c5f91a176f5',626,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
