insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sticky-sesame-turkey-meatballs','Sticky Sesame Turkey Meatballs','dinner','🥢',2,636,49,87,12,array['Heat the oven to 200C (180C fan). Mix the turkey mince, half the sliced spring onions, half the garlic, breadcrumbs, egg, grated ginger, chilli flakes, half the soy sauce and the sesame oil, then shape into 10 balls.','Bake the meatballs on a lined tray for 16 to 18 minutes until golden and cooked through with no pink inside. Meanwhile boil the rice for 10 to 12 minutes.','For the sauce, put the honey, remaining soy sauce, garlic, the white of the remaining spring onions, the juice of half the lime and 100ml water in a small pan. Stir the cornflour with 1 tablespoon water, add it and simmer for 3 to 5 minutes until thick and glossy. Stir in the green spring onion and half the sesame seeds.','Boil the broccoli for 3 to 4 minutes, then drain. Toss the cooked meatballs in the sauce until coated, then serve over the rice with the broccoli, the remaining sesame seeds and a wedge of the remaining lime.']::text[],array['eggs','gluten','sesame','soya']::text[],'live','idea: Mob',false,'3f1c458a2b316e60',286,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
