insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('summer-bbq-chicken-corn','Summer BBQ Chicken with Corn','dinner','🌽',2,536,40,27,29,array['Toss the chicken thighs with the barbecue sauce in a bowl and leave to marinate for 15 minutes, or longer if you have time.','Mix the chopped avocado, tomatoes, salad and shredded cabbage in a large bowl. Whisk the yoghurt, oil and vinegar with a pinch of salt and pepper, pour over the salad and toss.','Put the corn in a covered bowl with a splash of water and microwave for 4 minutes.','Heat a griddle pan over a high heat until very hot, then cook the chicken for 3 to 4 minutes on each side until charred and cooked through.','Cook the corn on the griddle for 5 minutes, turning now and then, until lightly charred all over.','Serve the chicken with the salad and corn, spreading the butter over the corn with a pinch of salt.']::text[],array['gluten','milk','sulphites']::text[],'live','idea: Joe Wicks',false,'af50e77d5cb98cc5',303,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
