insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sweet-chilli-beef-skewers-and-rice','Sweet Chilli Beef Skewers with Veg Rice','dinner','🍢',4,415,24,70,6,array['Soak 8 wooden skewers in water for 10 minutes. Cook the rice to the packet instructions, about 12 minutes, then drain.','Heat the grill to medium-high. Toss the beef strips and halved tomatoes with two thirds of the sweet chilli sauce, then thread onto the skewers.','Grill the skewers for 6 minutes, turning once, until the beef is cooked through.','Meanwhile heat the oil in a wok and stir-fry the baby corn, sugar snap peas and spring onions for 2 minutes, adding a splash of water to steam.','Add the rice and the rest of the sweet chilli sauce and cook for 2 minutes until hot. Serve the skewers on the rice with lime wedges and torn coriander.']::text[],array[]::text[],'live','idea: Sainsbury''s recipes',false,'6ef626078ebc89fd',228,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
