insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sweet-potato-and-chickpea-curry-with-naan','Sweet Potato and Chickpea Curry with Naan','dinner','🍠',2,852,23,119,30,array['Dice the sweet potato and drain the chickpeas. Heat the oil in a large pan and soften the sweet potato for 5 minutes, stirring now and then.','Stir in the tikka paste for 1 minute, then add the chickpeas, passata and coconut milk. Bring to the boil, then turn the heat down.','Simmer for 20 minutes until the sweet potato is tender, adding a splash of water if it gets too thick.','Stir through the spinach for 2 minutes until wilted. Warm the naans in a toaster or dry pan and serve with the curry.']::text[],array['gluten','milk']::text[],'live','table-plan',false,'c1de3f5970ea7172',191,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
