insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sweet-potato-and-egg-hash','Sweet Potato and Egg Hash','breakfast','🍠',1,380,16,49,15,array['Dice the sweet potato, chop the onion and deseed and chop the pepper.','Heat the oil in a frying pan and fry the sweet potato for 10 minutes until soft and golden. Add the onion, pepper and paprika and cook for 3 minutes.','Make two wells in the hash, crack in the eggs, cover the pan and cook for 3 to 4 minutes until the whites are set.','Season with salt and pepper and serve straight from the pan.']::text[],array['eggs']::text[],'live','table-plan',false,'8ca5729fe8d5f6f3',135,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
