insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sweet-potato-chilli-bake','Sweet Potato Chilli Bake','dinner','🍠',2,612,23,94,17,array['Heat the oven to 200C (180C fan). Prick the sweet potatoes all over with a fork and bake for 45 minutes until soft.','Meanwhile, heat the oil in a pan and soften the chopped onion and pepper for 5 minutes. Stir in the cumin and paprika for 1 minute.','Add the chopped tomatoes and drained kidney beans and simmer for 20 minutes until thick. Season with salt and pepper.','Split the baked potatoes, spoon over the chilli and top with grated cheddar to serve.']::text[],array['milk']::text[],'live','table-plan',false,'deb864eef7fdf0a2',139,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
