insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('sweet-potato-cottage-pie','Sweet Potato Cottage Pie','dinner','🥧',4,460,32,56,12,array['Peel the sweet potatoes, cut into chunks and boil for 15 minutes until soft. Drain, mash and stir in the yoghurt.','Brown the mince in the oil in a large pan, then add the chopped onion and grated carrot and cook for 5 minutes.','Add the tomatoes, crumbled stock cube, oregano and a splash of water and simmer for 10 minutes until thick.','Spoon the mince into a dish, top with the mash and grill or bake at 200C for 10 to 15 minutes until crisp at the edges. Serve with the peas.']::text[],array['eggs','milk']::text[],'live','idea: Joe Wicks',false,'a06475b42ef9490e',214,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
