insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('tandoori-chicken-kebab-bean-biryani','Tikka Chicken Kebab with Green Bean Biryani','dinner','🍢',4,537,39,68,14,array['Soak the rice in cold water for 30 minutes. Meanwhile mix the tikka paste and yoghurt in a large bowl, stir in half the chopped coriander, add the chicken thighs, coat well, cover and chill.','Melt the butter with the oil in a lidded pan and fry the sliced onion over a gentle heat for 6 minutes until soft and golden. Drain the rice and stir it in with the curry powder.','Pour in 750ml hot water with the crumbled stock cubes, add the green beans, bring to the boil, cover and cook on a low heat for 10 minutes.','Heat the grill to high. Lay the chicken thighs side by side with the long edges touching and push two long skewers through to hold them as one large kebab.','Grill the kebab for 20 minutes, turning the skewers a couple of times, until browned and cooked through with no pink where the thighs meet.','Spoon the biryani onto a platter, top with the kebab, scatter with the remaining coriander and serve with lemon wedges.']::text[],array['eggs','milk']::text[],'live','idea: Morrisons Recipes (Good Food)',false,'df08d0f9637f955f',203,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
