insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('tandoori-chicken-skewers-and-rice','Tandoori Chicken Skewers & Rice','dinner','🍢',2,539,51,67,9,array['Cut the chicken into 3cm chunks. Mix half the yoghurt with the paprika, cumin, curry powder, tomato puree, crushed garlic and the lemon juice, then coat the chicken and marinate for 15 minutes.','Thread the chicken onto skewers. Oven method: heat the oven to 220C (200C fan) and roast on a tray for 15 minutes, turning once, until charred and cooked through. In an air fryer, cook at 200C for 6 to 8 minutes in a single layer.','Cook the rice following the pack instructions, about 12 minutes, then drain and fluff with a fork.','Mix the rest of the yoghurt with the chopped coriander, the lime juice, salt and pepper for a cooling dip.','Serve the skewers on the rice with the coriander and lime yoghurt spooned over.']::text[],array['milk']::text[],'live','idea: Mob',false,'0f16d7b0b0b6cb93',176,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
