insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('texan-beef-burritos','Texan Beef Burritos','dinner','🌯',4,847,47,93,30,array['Brown the beef mince in a pan for 5 minutes until no pink remains. Set aside 2 tablespoons of the BBQ sauce, stir the rest into the mince with the chopped tomatoes and simmer for 10 minutes until cooked through and thick.','Heat the grill to high. Warm the drained kidney beans in the oil with 3 tablespoons of water for 3 minutes, then mash them coarsely with a fork.','Warm the wraps for 30 seconds in the microwave. Spread the beans down the middle of each, spoon on the beef and roll up into burritos.','Lay the burritos seam side down on a baking tray, brush with the reserved sauce, scatter over the cheddar and grill for 2 minutes until melted and golden.','Mash the avocado with a pinch of salt and serve it alongside the burritos.']::text[],array['gluten','milk']::text[],'live','idea: Sainsbury''s recipes',false,'48498b32e5f1510a',267,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
