insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('thai-basil-chicken-stir-fry','Thai Basil Chicken Stir-Fry','dinner','🌿',2,659,52,78,18,array['Cook the rice following the packet, about 12 minutes, then drain and keep warm. Slice the pepper, onion, chilli and garlic, cut the green beans into 2cm pieces and pick the Thai basil leaves.','Slice the chicken, halve the slices and toss with 1 teaspoon of the fish sauce. Mix the rest of the fish sauce with the oyster sauce, soy sauce, dark soy and honey. Stir a little of the rice vinegar with some chilli for a dressing.','Heat half the oil in a large pan over a high heat and sear the chicken for 3 minutes until golden. Tip it into a bowl, it will finish cooking later.','Add the remaining oil and stir-fry the pepper, onion and chilli for 3 minutes. Add the garlic, then the beans with 2 tablespoons of water for 1 minute.','Return the chicken, pour in the sauce and cook for 2 to 3 minutes until thick and the chicken is cooked through. Off the heat, stir in the basil. Fry the eggs to your liking.','Serve the rice topped with the stir-fry, a fried egg, lime wedges and the dressing.']::text[],array['eggs','fish','gluten','molluscs','soya','sulphites']::text[],'live','idea: Mob',false,'5a2b110440084435',328,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
