insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('thai-chicken-and-broccoli-curry','Thai Chicken and Broccoli Curry','dinner','🍛',4,583,33,72,19,array['Cook the rice to the packet instructions, about 12 minutes, then drain and keep warm.','Heat the oil in a deep frying pan or wok and stir-fry the sliced onion for 5 minutes until golden, then lift out. Fry the chopped chicken thighs for 5 minutes until coloured all over.','Return the onion with the broccoli and sliced carrot and stir-fry for 2 minutes. Stir in the curry paste for 1 minute.','Pour in the coconut milk and 150ml water and simmer for 6 to 8 minutes until the chicken is cooked through and the vegetables are tender.','Spoon the curry over the rice and serve.']::text[],array[]::text[],'live','idea: Sainsbury''s recipes (Thai green chicken curry, red paste swap)',false,'9f3777b0c8915bee',171,'low',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
