insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('thai-red-curry-cod-parcels','Thai Red Curry Cod Parcels','dinner','🐟',2,455,28,60,13,array['Heat the oven to 200C (180C fan). Boil the basmati rice for 10 to 12 minutes until tender, then drain.','Whisk the coconut milk with the curry paste, fish sauce and the finely grated zest of half the lime. Halve the sugar snap peas lengthways and toss them with the oil.','Divide the peas between two large sheets of baking parchment, set a cod fillet on each and spoon over the coconut mixture. Fold and seal the parcels tightly and place on a baking tray.','Bake for 12 to 15 minutes until the fish flakes easily and the peas are tender. Open the parcels, squeeze over the juice of one lime, then serve with the rice, sliced chilli, coriander and lime wedges, spooning the sauce over.']::text[],array['fish']::text[],'live','idea: Mob',false,'6a35665dfa7a5009',466,'high',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
