insert into public.recipes (slug,name,course,emoji,serves,kcal,protein_g,carbs_g,fat_g,method,allergens,status,source,macros_only,content_hash,cost_pence,budget,image_alt,image_colour) values ('turkey-meatball-pepper-pasta','Turkey Meatball & Red Pepper Pasta','dinner','🍝',2,492,43,55,12,array['Cook the spaghetti in boiling salted water for about 10 minutes, then drain. At the same time, simmer the sliced peppers in a small pan with a splash of water and the lid on for 10 minutes until very soft.','Mix the turkey mince with the herbs, garlic and plenty of black pepper, then roll into small even meatballs.','Fry the meatballs in the oil in a large frying pan for 8 minutes, turning, until golden and cooked through.','Blitz the soft peppers until smooth, pour them over the meatballs and heat through for 2 minutes.','Take the pan off the heat and stir in the yoghurt to make a creamy sauce, then season to taste.','Divide the spaghetti between bowls and top with the meatballs and sauce.']::text[],array['gluten','milk']::text[],'live','idea: Joe Wicks',false,'242fcb3605ebd8d5',237,'medium',null,null) on conflict (slug) do update set name=excluded.name,course=excluded.course,emoji=excluded.emoji,serves=excluded.serves,kcal=excluded.kcal,protein_g=excluded.protein_g,carbs_g=excluded.carbs_g,fat_g=excluded.fat_g,method=excluded.method,allergens=excluded.allergens,status=excluded.status,source=excluded.source,macros_only=excluded.macros_only,content_hash=excluded.content_hash,cost_pence=excluded.cost_pence,budget=excluded.budget,image_alt=excluded.image_alt,image_colour=excluded.image_colour where public.recipes.content_hash is distinct from excluded.content_hash;
